"""Self-contained numpy model for dd8_r4_MRMR_513_nw (generated by mk_model.py).

Construction (matches directed_design/gen_verilog.py):
  round i: x = LIN_i(P(SBOX_i(x ^ rk_i)))
  LIN_i(x) = x ^ rotl64(x,a) ^ rotl64(x,b)  (a,b per round: [5, 13])
  P: out[P[i]] = in[i]
  rk_i = rk_i = rotl64(key,13*(i+1)) ^ RC[i]
"""
import numpy as np

SBOX_ROUNDS = [[12, 10, 13, 3, 14, 11, 15, 7, 8, 9, 1, 5, 0, 2, 4, 6], [0, 1, 2, 3, 4, 6, 8, 11, 13, 9, 7, 15, 12, 10, 5, 14], [12, 10, 13, 3, 14, 11, 15, 7, 8, 9, 1, 5, 0, 2, 4, 6], [0, 1, 2, 3, 4, 6, 8, 11, 13, 9, 7, 15, 12, 10, 5, 14]]
PBOX = [1, 20, 39, 58, 13, 32, 51, 6, 25, 44, 63, 18, 37, 56, 11, 30, 49, 4, 23, 42, 61, 16, 35, 54, 9, 28, 47, 2, 21, 40, 59, 14, 33, 52, 7, 26, 45, 0, 19, 38, 57, 12, 31, 50, 5, 24, 43, 62, 17, 36, 55, 10, 29, 48, 3, 22, 41, 60, 15, 34, 53, 8, 27, 46]
RC = np.array([11400714819323198485, 4354685564936845354, 15755400384260043839, 8709371129873690708], dtype=np.uint64)
M64 = np.uint64(0xFFFFFFFFFFFFFFFF)
ROUNDS = 4
ROTS = [5, 13]
KS_ROT_STEPS = [13]


def _rots(r):
    if isinstance(ROTS[0], (list, tuple)):
        return ROTS[r][0], ROTS[r][1]
    return ROTS[0], ROTS[1]


def _rotl(x, r):
    r %= 64
    if r == 0:
        return x
    return ((x << np.uint64(r)) | (x >> np.uint64(64 - r))) & M64


def _sbox64(x, r):
    sb = np.array(SBOX_ROUNDS[r], dtype=np.uint64)
    y = np.zeros_like(x)
    for i in range(16):
        y |= sb[((x >> np.uint64(4 * i)) & np.uint64(0xF))] << np.uint64(4 * i)
    return y & M64


def _pbox64(x):
    y = np.zeros_like(x)
    for i in range(64):
        y |= ((x >> np.uint64(i)) & np.uint64(1)) << np.uint64(PBOX[i])
    return y & M64


def _lin(x, r):
    a, b = _rots(r)
    return (x ^ _rotl(x, a) ^ _rotl(x, b)) & M64


def _round(x, key, i):
    rk = np.uint64(0)
    for s in KS_ROT_STEPS:
        rk ^= _rotl(key, s * (i + 1))
    rk ^= RC[i]
    return _lin(_pbox64(_sbox64(x ^ rk, i)), i)


def mix_np(V, K):
    x = np.asarray(V, dtype=np.uint64)
    k = np.asarray(K, dtype=np.uint64)
    for i in range(ROUNDS):
        x = _round(x, k, i)
    return x & M64


def mix(v, k):
    return int(mix_np(np.uint64(v), np.uint64(k)))
